additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

struct Tracked {
    static inline int move_assigns = 0;
    std::string v;

    explicit Tracked(std::string s) : v(std::move(s)) {}
    Tracked(Tracked &&) noexcept = default;
    Tracked &operator=(Tracked &&other) noexcept {
        v = std::move(other.v);
        ++move_assigns;
        return *this;
    }
};

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream in(line);
    std::vector<Tracked> items;
    std::string w;
    while (in >> w) {
        items.emplace_back(w);
    }
    std::string command;
    while (std::cin >> command) {
        if (command == "erase") {
            std::ptrdiff_t i;
            std::cin >> i;
            items.erase(items.begin() + i);
        } else if (command == "erase-if") {
            std::string s;
            std::cin >> s;
            std::erase_if(items, [&](const Tracked &t) { return t.v == s; });
        } else {
            std::string text;
            for (const Tracked &t : items) {
                text += (text.empty() ? "" : " ") + t.v;
            }
            std::println("{} (присваиваний {})", text.empty() ? "—" : text, Tracked::move_assigns);
        }
    }
    return 0;
}

