additionalExercises.referenceSolution:
#include <iostream>
#include <iterator>
#include <map>
#include <print>
#include <string>
#include <utility>

struct Pool {
    int next = 1;
    int open = 0;

    int acquire() {
        ++open;
        std::println("открыт {}", next);
        return next++;
    }

    void release(int id) {
        --open;
        std::println("закрыт {}", id);
    }
};

Pool pool;

class UniqueHandle {
public:
    UniqueHandle() = default;
    explicit UniqueHandle(int id) : id_(id) {}
    UniqueHandle(const UniqueHandle &) = delete;
    UniqueHandle &operator=(const UniqueHandle &) = delete;
    UniqueHandle(UniqueHandle &&other) noexcept : id_(std::exchange(other.id_, 0)) {}
    UniqueHandle &operator=(UniqueHandle &&other) noexcept {
        if (this != &other) {
            reset();
            id_ = std::exchange(other.id_, 0);
        }
        return *this;
    }
    ~UniqueHandle() {
        reset();
    }

    int id() const {
        return id_;
    }

private:
    void reset() {
        if (id_ != 0) {
            pool.release(std::exchange(id_, 0));
        }
    }

    int id_ = 0;
};

int main() {
    std::map<std::string, UniqueHandle> handles;
    std::string command;
    while (std::cin >> command) {
        if (command == "open-count") {
            std::println("открыто {}", pool.open);
            continue;
        }
        std::string x;
        std::cin >> x;
        if (command == "open") {
            handles[x] = UniqueHandle(pool.acquire());
        } else if (command == "move") {
            std::string y;
            std::cin >> y;
            handles[x] = std::move(handles[y]);
        } else if (command == "close") {
            handles[x] = UniqueHandle();
        } else {
            const int id = handles[x].id();
            if (id == 0) {
                std::println("{}: пусто", x);
            } else {
                std::println("{}: {}", x, id);
            }
        }
    }
    while (!handles.empty()) {
        handles.erase(std::prev(handles.end()));
    }
    return 0;
}

